"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/step-form/variants/01-focused";
import View1 from "./components/step-form/variants/02-card-stack";
import View2 from "./components/step-form/variants/03-inline-prompt";
import View3 from "./components/step-form/variants/04-onboarding";
function CompactOnboarding(){return <View3 compact/>;}
const variants={"focused":View0,"card-stack":View1,"inline-prompt":View2,"onboarding":View3,"onboarding-compact":CompactOnboarding};
export interface ArtemisStepFormProps { className?: string; variant?: "focused" | "card-stack" | "inline-prompt" | "onboarding" | "onboarding-compact"; }
export function ArtemisStepForm({className,variant="focused"}:ArtemisStepFormProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useState, type FormEvent } from "react";
import { ArrowLeft, ArrowRight, Check, RotateCcw } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { Field } from "./01-focused/field";
import { Choices, type Choice } from "./01-focused/choices";
type Key = "name" | "team" | "goal" | "email";
type Step = {
    id: Key;
    label: string;
    question: string;
    description?: string;
} & ({
    kind: "text" | "email";
    placeholder: string;
} | {
    kind: "choice";
    options: readonly Choice[];
});
const STEPS: readonly Step[] = [
    { id: "name", label: "Introduction", question: "What should we call you?", description: "A first name is enough.", kind: "text", placeholder: "Your name" },
    { id: "team", label: "Team size", question: "How do you usually build?", description: "Choose the setup closest to yours.", kind: "choice", options: [{ label: "Solo", description: "Just me for now" }, { label: "Small team", description: "2\u201310 people" }, { label: "Growing team", description: "11+ people" }] },
    { id: "goal", label: "Main goal", question: "What would make this useful?", kind: "choice", options: [{ label: "Launch something new" }, { label: "Improve an existing product" }, { label: "Explore what is possible" }] },
    { id: "email", label: "Last step", question: "Where should we send the plan?", description: "No newsletters. Just the project summary.", kind: "email", placeholder: "you@company.com" },
];
const EMPTY: Record<Key, string> = { name: "", team: "", goal: "", email: "" };
const GHOST = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground";
const RING = "art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const PRIMARY = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full";
export default function StepFormFocused() {
    const reduce = useReducedMotion();
    const [step, setStep] = useState(0);
    const [direction, setDirection] = useState(1);
    const [answers, setAnswers] = useState(EMPTY);
    const [error, setError] = useState("");
    const done = step === STEPS.length;
    const active = Math.min(step, STEPS.length - 1);
    const current = STEPS[active]!;
    const transition = reduce ? { duration: 0 } : { duration: 0.22, ease: ARTEMIS_EASE_OUT };
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    function submit(event: FormEvent) {
        event.preventDefault();
        if (done)
            return;
        const value = answers[current.id].trim();
        if (!value) {
            setError("Please complete this step.");
            return;
        }
        if (current.kind === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
            setError("Enter a valid email address.");
            return;
        }
        setError("");
        setDirection(1);
        setStep(value => value + 1);
    }
    function back() { setError(""); setDirection(-1); setStep(value => Math.max(0, value - 1)); }
    function reset() { setAnswers(EMPTY); setError(""); setDirection(-1); setStep(0); }
    function change(value: string) { setAnswers(previous => ({ ...previous, [current.id]: value })); setError(""); }
    return <div className="art:flex art:w-full art:items-center art:justify-center">
    <section className="art:w-full">
      <div className="art:mx-auto art:w-full art:max-w-xl art:overflow-hidden art:rounded-xl art:border art:border-border/60 art:bg-background">
        <div className="art:flex art:items-center art:justify-between art:border-border/50 art:border-b art:px-5 art:py-4 art:@min-[640px]/artemis:px-7">
          <div className="art:flex art:items-center art:gap-2">{STEPS.map((item, index) => <span key={item.id} aria-hidden="true" className={`art:h-1 art:w-6 art:overflow-hidden art:rounded-full ${index < active ? "art:@min-[640px]/artemis:w-8 art:bg-foreground" : "art:bg-border/60 art:@min-[640px]/artemis:w-8"}`}>{index === active && <motion.span className="art:block art:h-full art:origin-left art:rounded-full art:bg-foreground" initial={reduce ? false : { scaleX: 0 }} animate={{ scaleX: 1 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>}</span>)}</div>
          <span className="art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">{done ? "Done" : `${String(step + 1).padStart(2, "0")} / 04`}</span>
        </div>
        <form noValidate onSubmit={submit}>
          <AnimatePresence mode="wait" initial={false}>
            <motion.div key={done ? "done" : current.id} className={done ? "art:px-5 art:py-10 art:text-center art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-12" : "art:px-5 art:py-7 art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-9"} initial={reduce ? false : { opacity: 0, transform: `translateX(${direction * 14}px)`, filter: "blur(3px)" }} animate={{ opacity: 1, transform: "translateX(0px)", filter: "blur(0px)" }} exit={{ opacity: 0, transform: `translateX(${-direction * 10}px)`, filter: "blur(2px)" }} transition={transition}>
              {done ? <>
                <span className="art:mx-auto art:grid art:size-12 art:place-items-center art:rounded-full art:border art:border-foreground art:text-foreground"><svg aria-hidden="true" viewBox="0 0 24 24" className="art:size-6" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><motion.path d="m5 12 4 4L19 6" initial={reduce ? false : { opacity: 0, pathLength: 0 }} animate={{ opacity: 1, pathLength: 1 }} transition={reduce ? { duration: 0 } : { duration: 0.35, delay: 0.08, ease: ARTEMIS_EASE_OUT }}/></svg></span>
                <h2 className="art:mt-5 art:text-foreground art:tracking-tight art:text-xl art:font-medium">Your plan is ready.</h2>
                <p className="art:mx-auto art:mt-2 art:max-w-sm art:text-muted-foreground art:text-sm art:leading-6">We saved your answers and prepared the next steps.</p>
                <motion.button type="button" className={`${GHOST} art:gap-1.5 art:px-3 art:text-xs ${RING} art:mt-6 art:h-9 art:rounded-full`} tabIndex={0} onClick={reset} {...press}><RotateCcw className="art:size-3.5"/>{"Start again"}</motion.button>
              </> : <>
                <p className="art:font-mono art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{current.label}</p>
                <h2 className="art:mt-3 art:max-w-md art:text-foreground art:tracking-tight art:@min-[640px]/artemis:leading-9 art:text-xl art:font-medium">{current.question}</h2>
                {current.description && <p className="art:mt-2 art:text-muted-foreground art:text-sm art:leading-6">{current.description}</p>}
                <div className="art:mt-7">{current.kind === "choice" ? <Choices id={current.id} question={current.question} options={current.options} value={answers[current.id]} error={error} onChange={change}/> : <Field id={current.id} question={current.question} type={current.kind} placeholder={current.placeholder} value={answers[current.id]} error={error} onChange={change}/>}</div>
                <div className="art:mt-5 art:flex art:items-center art:justify-between art:gap-3">
                  <motion.button type="button" className={`${GHOST} art:gap-2 art:px-5 art:text-sm ${RING} art:-ml-3 art:h-9 art:rounded-full`} disabled={step === 0} tabIndex={0} onClick={back} {...press}><ArrowLeft className="art:size-4"/>{"Back"}</motion.button>
                  <motion.button type="submit" className={PRIMARY} tabIndex={0} {...press}>{current.kind === "email" ? "Create my plan" : "Continue"}{current.kind === "email" ? <Check className="art:size-4"/> : <ArrowRight className="art:size-4"/>}</motion.button>
                </div>
              </>}
            </motion.div>
          </AnimatePresence>
        </form>
      </div>
    </section>
  </div>;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useId } from "react";
import { Check } from "lucide-react";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
export type Choice = {
    label: string;
    description?: string;
};
const BASE = "art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:bg-transparent art:hover:text-inherit art:relative art:isolate art:flex art:min-h-14 art:w-full art:items-center art:justify-between art:gap-4 art:overflow-hidden art:border art:border-border/60 art:px-4 art:py-3 art:text-left art:text-foreground art:outline-none art:transition-colors art:focus-visible:bg-muted";
export function Choices({ id, question, options, value, error, onChange }: {
    id: string;
    question: string;
    options: readonly Choice[];
    value: string;
    error: string;
    onChange: (value: string) => void;
}) {
    const reduce = useReducedMotion();
    const layoutId = useId();
    const transition = reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT;
    return <fieldset className="art:grid art:gap-2" aria-describedby={`${id}-error`}>
    <legend className="art:sr-only">{question}</legend>
    {options.map(option => {
            const on = value === option.label;
            return <motion.button key={option.label} type="button" className={`${BASE}${on ? "" : " art:hover:border-border"} art:rounded-full`} aria-pressed={on} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => onChange(option.label)}>
        {on && <motion.span aria-hidden="true" layoutId={layoutId} className="art:absolute art:inset-0 art:-z-10 art:bg-muted" initial={reduce ? false : { opacity: 0, scale: 0.985 }} animate={{ opacity: 1, scale: 1 }} transition={transition}/>}
        <span className="art:min-w-0"><span className="art:block art:font-medium art:text-sm">{option.label}</span>{option.description && <span className="art:mt-0.5 art:block art:text-muted-foreground art:text-xs art:leading-5">{option.description}</span>}</span>
        <motion.span className={`art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:border ${on ? "art:border-foreground art:bg-foreground art:text-background" : "art:border-border art:text-transparent"}`} initial={false} animate={{ opacity: reduce || on ? 1 : 0.45, scale: reduce ? 1 : on ? 1 : 0.82, rotate: reduce ? 0 : on ? 0 : -8 }} transition={transition}><Check className="art:size-3" strokeWidth={2.5}/></motion.span>
      </motion.button>;
        })}
    <p id={`${id}-error`} aria-live="polite" className="art:min-h-6 art:pt-1.5 art:text-destructive art:text-xs">{error}</p>
  </fieldset>;
}

"use client";
// @zeus-internal
import { ArtemisValidationFrame } from "../../../../lib/validation-frame";
export function Field({id,question,type,placeholder,value,error,onChange}:{id:string;question:string;type:"text"|"email";placeholder:string;value:string;error:string;onChange:(value:string)=>void}) {
 return <div><label htmlFor={id} className="art:sr-only">{question}</label><ArtemisValidationFrame error={!!error}><input id={id} name={id} type={type} autoComplete={type==="email"?"email":"given-name"} placeholder={placeholder} value={value} onChange={event=>onChange(event.target.value)} aria-invalid={!!error || undefined} aria-describedby={`${id}-error`} className="art:h-full art:w-full art:bg-transparent art:px-4 art:text-base art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/65"/></ArtemisValidationFrame><p id={`${id}-error`} aria-live="polite" className="art:min-h-6 art:pt-1.5 art:text-xs art:text-destructive">{error}</p></div>;
}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { AnimatePresence, motion, useAnimationControls, useReducedMotion } from "motion/react";
import { type FormEvent, type ReactNode, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
type ChoiceStep = {
    kind: "choice";
    id: string;
    label: string;
    question: string;
    options: readonly string[];
};
type EmailStep = {
    kind: "email";
    id: string;
    label: string;
    question: string;
};
const STEPS: readonly (ChoiceStep | EmailStep)[] = [
    { kind: "choice", id: "project", label: "Project", question: "What are you planning?", options: ["A new website", "A product experience", "A focused redesign"] },
    { kind: "choice", id: "timing", label: "Timing", question: "When should it be ready?", options: ["As soon as possible", "Within a month", "Still exploring"] },
    { kind: "email", id: "contact", label: "Contact", question: "Where can we follow up?" },
];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const SWAP = { duration: 0.225, ease: ARTEMIS_EASE_OUT };
const OPTION_BASE = "art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:bg-transparent art:hover:text-inherit art:relative art:isolate art:flex art:min-h-14 art:w-full art:items-center art:justify-between art:gap-4 art:overflow-hidden art:border art:border-border/60 art:px-4 art:py-3 art:text-left art:text-foreground art:outline-none art:transition-colors art:focus-visible:bg-muted";
const GHOST = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground";
const PRIMARY = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full";
const RING = "art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
function Svg({ name, size, stroke = "2", children }: {
    name: string;
    size: string;
    stroke?: string;
    children: ReactNode;
}) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-${name} ${size}`} aria-hidden="true">
      {children}
    </svg>);
}
const ArrowRight = () => (<Svg name="arrow-right" size="art:size-4">
    <path d="M5 12h14"/>
    <path d="m12 5 7 7-7 7"/>
  </Svg>);
export default function StepFormCardStack() {
const artemisInstanceId = useArtemisInstanceId();

    const reduce = useReducedMotion();
    const [step, setStep] = useState(0);
    const [answers, setAnswers] = useState<Record<string, string>>({});
    const [email, setEmail] = useState("");
    const [error, setError] = useState("");
    const shake = useAnimationControls();
    const done = step === STEPS.length;
    const current = STEPS[Math.min(step, STEPS.length - 1)];
    const submit = (e: FormEvent) => {
        e.preventDefault();
        if (done)
            return;
        if (current.kind === "choice") {
            if (!answers[current.id]) {
                setError("Please complete this step.");
                return;
            }
        }
        else if (!EMAIL.test(email.trim())) {
            setError(email.trim() ? "Enter a valid email address." : "Please complete this step.");
            if (!reduce)
                void shake.start({ x: [0, -6, 6, -4, 4, -2, 0], transition: { duration: 0.45 } });
            return;
        }
        setError("");
        setStep((s) => s + 1);
    };
    const back = () => {
        setError("");
        setStep((s) => Math.max(0, s - 1));
    };
    const restart = () => {
        setAnswers({});
        setEmail("");
        setError("");
        setStep(0);
    };
    return (<>
      <div className="art:flex art:w-full art:items-center art:justify-center">
        <section className="art:w-full">
          <div className="art:relative art:mx-auto art:w-full art:max-w-lg art:pb-4">
            <div className="art:absolute art:inset-x-8 art:top-4 art:bottom-0 art:rounded-2xl art:bg-muted/30"/>
            <div className="art:absolute art:inset-x-4 art:top-2 art:bottom-2 art:rounded-2xl art:bg-muted/55"/>
            <div className="art:relative art:overflow-hidden art:rounded-2xl art:border art:border-border/60 art:bg-background">
              <div className="art:flex art:items-center art:justify-between art:px-5 art:pt-5 art:@min-[640px]/artemis:px-7">
                <button type="button" className={`${GHOST} ${RING} art:size-9 art:-ml-2 art:h-9 art:rounded-full`} aria-label="Previous step" tabIndex={0} disabled={step === 0 || done} onClick={back}>
                  <Svg name="arrow-left" size="art:size-4">
                    <path d="m12 19-7-7 7-7"/>
                    <path d="M19 12H5"/>
                  </Svg>
                </button>
                <span className="art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">{done ? "Complete" : `${step + 1} of ${STEPS.length}`}</span>
              </div>
              <form noValidate onSubmit={submit}>
                <AnimatePresence mode="wait" initial={false}>
                  {done ? (<motion.div key="done" className="art:px-6 art:pt-8 art:pb-10 art:text-center art:@min-[640px]/artemis:px-9" initial={{ opacity: 0, transform: "translateY(16px) scale(0.985)" }} animate={{ opacity: 1, transform: "translateY(0px) scale(1)" }} exit={{ opacity: 0, transform: "translateY(-16px) scale(0.985)" }} transition={SWAP}>
                      <motion.span className="art:mx-auto art:grid art:size-11 art:place-items-center art:rounded-full art:bg-foreground art:text-background" initial={reduce ? false : { opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} transition={{ type: "spring", stiffness: 420, damping: 26, delay: 0.08 }}>
                        <Svg name="check" size="art:size-5">
                          <path d="M20 6 9 17l-5-5"/>
                        </Svg>
                      </motion.span>
                      <h2 className="art:mt-5 art:text-foreground art:tracking-tight art:text-xl art:font-medium">Brief received.</h2>
                      <p className="art:mx-auto art:mt-2 art:max-w-sm art:text-muted-foreground art:text-sm art:leading-6">We will review the details and follow up shortly.</p>
                      <button type="button" className={`${GHOST} art:gap-1.5 art:px-3 art:text-xs ${RING} art:mt-5 art:h-9 art:rounded-full`} tabIndex={0} onClick={restart}>
                        <Svg name="rotate-ccw" size="art:size-3.5">
                          <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/>
                          <path d="M3 3v5h5"/>
                        </Svg>
                        Start again
                      </button>
                    </motion.div>) : (<motion.div key={current.id} className="art:px-6 art:pt-7 art:pb-7 art:@min-[640px]/artemis:px-9 art:@min-[640px]/artemis:pb-9" initial={{ opacity: 0, transform: "translateY(16px) scale(0.985)" }} animate={{ opacity: 1, transform: "translateY(0px) scale(1)" }} exit={{ opacity: 0, transform: "translateY(-16px) scale(0.985)" }} transition={SWAP}>
                      <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.14em]">{current.label}</p>
                      <h2 className="art:mt-2 art:text-foreground art:tracking-tight art:text-xl art:font-medium">{current.question}</h2>
                      <div className="art:mt-6">
                        {current.kind === "choice" ? (<fieldset className="art:grid art:gap-2" aria-describedby={`${current.id}-error`}>
                            <legend className="art:sr-only">{current.question}</legend>
                            {current.options.map((option) => {
                    const on = answers[current.id] === option;
                    return (<motion.button key={option} type="button" className={`${OPTION_BASE}${on ? "" : " art:hover:border-border"} art:rounded-full`} aria-pressed={on} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} onClick={() => {
                            setAnswers((a) => ({ ...a, [current.id]: option }));
                            setError("");
                        }}>
                                  {on && (<motion.span aria-hidden="true" className="art:absolute art:inset-0 art:-z-10 art:bg-muted" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={SWAP}/>)}
                                  <span className="art:min-w-0">
                                    <span className="art:block art:font-medium art:text-sm">{option}</span>
                                  </span>
                                  <motion.span className={`art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:border ${on ? "art:border-foreground art:bg-foreground art:text-background" : "art:border-border art:text-transparent"}`} initial={false} animate={on ? { opacity: 1, transform: "none" } : { opacity: 0.45, transform: "scale(0.82) rotate(-8deg)" }} transition={{ type: "spring", stiffness: 500, damping: 30 }}>
                                    <Svg name="check" size="art:size-3" stroke="2.5">
                                      <path d="M20 6 9 17l-5-5"/>
                                    </Svg>
                                  </motion.span>
                                </motion.button>);
                })}
                            <p id={`${current.id}-error`} aria-live="polite" className="art:min-h-6 art:pt-1.5 art:text-destructive art:text-xs">
                              {error}
                            </p>
                          </fieldset>) : (<div>
                            <label htmlFor={`${artemisInstanceId}-contact`} className="art:sr-only">
                              {current.question}
                            </label>
                            <div className="art:flex art:flex-col art:gap-1.5 art:w-full">
                              <motion.div data-state={error ? "error" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${error ? "art:border-destructive" : "art:border-border"}`} animate={shake}>
